<?php use App\Core\Helpers as H;$uid=(int)H::user()['id']; ?>
<header class="message-heading"><div><a href="/<?=$side?>/messages">← Inbox</a><h1><?=$side==='buyer'?H::e($conversation['shop_name']):H::e($conversation['buyer_name'])?></h1><p><?php if($conversation['context_label']):?>Context: <?=H::e($conversation['context_label'])?><?php endif;?><?php if($conversation['order_id']):?> · Order #<?=$conversation['order_id']?><?php endif;?></p></div></header>
<div class="thread-history"><?php if(!$messages):?><div class="card empty-state">No messages yet. Send the first message below.</div><?php endif;?><?php foreach($messages as $m):?><article class="thread-message <?=$m['sender_user_id']==$uid?'mine':'theirs'?>"><header><strong><?=H::e($m['sender_name'])?></strong><time><?=H::e($m['created_at'])?></time></header><?php if($m['body']!==null):?><p><?=nl2br(H::e($m['body']))?></p><?php endif;?><?php foreach($attachments[$m['id']]??[] as $a):?><a class="message-attachment" href="/messages/attachments/<?=$a['id']?>" target="_blank" rel="noopener"><img src="/messages/attachments/<?=$a['id']?>" alt="<?=H::e($a['original_name'])?>"><span><?=H::e($a['original_name'])?></span></a><?php endforeach;?></article><?php endforeach;?></div>
<?php if($blocked):?><p class="notice warning">New messages are disabled because one participant has blocked the other. History and reporting remain available.</p><?php else:?><form class="card form message-compose" method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=H::csrf()?>"><label for="message-body">Message</label><textarea id="message-body" name="body" maxlength="10000" rows="5"></textarea><label for="message-files">Images (JPG, PNG, or WEBP; up to 5, 10 MB each)</label><input id="message-files" type="file" name="attachments[]" accept="image/jpeg,image/png,image/webp" multiple><button class="btn">Send message</button></form><?php endif;?>
<div class="message-controls"><form method="post" action="/<?=$side?>/messages/<?=$conversation['id']?>/archive"><input type="hidden" name="_csrf" value="<?=H::csrf()?>"><input type="hidden" name="archive" value="<?=$conversation[$side.'_archived_at']?'0':'1'?>"><button><?=$conversation[$side.'_archived_at']?'Restore':'Archive'?></button></form><form method="post" action="/<?=$side?>/messages/<?=$conversation['id']?>/block"><input type="hidden" name="_csrf" value="<?=H::csrf()?>"><input type="hidden" name="block" value="<?=$myBlock?'0':'1'?>"><button><?=$myBlock?'Unblock':'Block'?></button></form></div>
<details class="card"><summary>Report conversation</summary><form class="form" method="post" action="/<?=$side?>/messages/<?=$conversation['id']?>/report"><input type="hidden" name="_csrf" value="<?=H::csrf()?>"><label>Reason<select name="reason" required><option value="">Choose</option><option value="abuse">Abuse</option><option value="spam">Spam</option><option value="inappropriate">Inappropriate messaging</option><option value="other">Other</option></select></label><label>Details<textarea name="details" maxlength="1000"></textarea></label><button>Submit report</button></form></details>
